try { $supplierId=filter_var($_POST['fornecedor_so_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($supplierId===false)throw new InvalidArgumentException('Fornecedor inválido.');$supplier=$application->soSuppliers()->findById($supplierId);if(!$supplier)throw new InvalidArgumentException('Fornecedor não encontrado.');if($application->adminCompanies()->integrationBySupplier($supplierId))throw new RuntimeException('Fornecedor já vinculado.');$document=preg_replace('/\D/','',$supplier->document)??'';if($document!==''&&$application->adminCompanies()->findByDocument($document))throw new RuntimeException('Documento já cadastrado.');$data=['razao_social'=>trim((string)($_POST['razao_social']??'')),'nome_fantasia'=>trim((string)($_POST['nome_fantasia']??'')),'documento'=>$document,'tipo_pessoa'=>trim((string)($_POST['tipo_pessoa']??'')),'segmento'=>trim((string)($_POST['segmento']??'')),'contato_responsavel'=>trim((string)($_POST['contato_responsavel']??$supplier->contact)),'telefone'=>trim((string)($_POST['telefone']??$supplier->phone)),'email'=>trim((string)($_POST['email']??'')),'status'=>trim((string)($_POST['status']??'pendente'))];foreach(['razao_social','tipo_pessoa','segmento'] as $field)if($data[$field]===''||str_contains($data[$field],"\0"))throw new InvalidArgumentException('Dados obrigatórios inválidos.');if($data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('E-mail inválido.');$id=$application->adminCompanies()->import($data,$currentUser->id(),$supplierId);$session->flash('success','Empresa aprovada e cadastrada com sucesso.');admin_action_redirect('adm/empresa.php?id='.$id); } catch(\Throwable $e){admin_action_error($e,'adm/empresas-so.php');}
